# Generated by build.py from recipe.yml for recipe pop3-refuse-a-second-session. Do not edit.
set -e
cd "$(dirname "$0")"
cat > report.eml <<'EOF'
From: shop@example.com
To: ann@example.com
Subject: Monthly report

Orders taken this month: 1,204.
Orders shipped this month: 1,187.
Orders returned this month: 31.
Orders still waiting for stock: 17.
Orders cancelled by the customer: 9.
The busiest day was the 14th, with 92 orders.
The quietest day was the 3rd, with 11 orders.
The warehouse in the north shipped 702 orders.
The warehouse in the south shipped 485 orders.
The average order was worth 38.20.
The largest order was worth 912.00.
Next month's report follows on the first working day.
EOF
cat > two-clients.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Two mail clients on Ann's maildrop at once. The first downloads message 1 slowly, so its
# session stays open; once the server has opened the maildrop for it, the second logs in.
# Usage: sh two-clients.sh <pop3 port>
url="pop3://127.0.0.1:$1"
opened=$(grep -c "Maildrop opened" surl.log)
curl -sS --limit-rate 100 -u ann@example.com:annpass -o first.eml "$url/1" &
first=$!
# Wait, at most ten seconds, until the server's log shows the first session's maildrop opened.
n=0
while [ "$(grep -c "Maildrop opened" surl.log)" -le "$opened" ] && [ $n -lt 50 ]; do sleep 0.2; n=$((n + 1)); done
curl -v -sS -u ann@example.com:annpass "$url/" 2> second.log
echo "second: exit $?"
grep -E "^< -ERR|^curl:" second.log | tr -d '\r'
wait $first
echo "first: exit $?"
EOF
surl -v --log-file surl.log --mail-domain example.com --mailbox shop@example.com:shoppass --mailbox ann@example.com:annpass smtp://127.0.0.1:8080/ pop3://127.0.0.1:8081/ &
sleep 1
curl -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T report.eml smtp://127.0.0.1:8080/shop.example.com
curl -sS -o /dev/null --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass -X "LIST 1" pop3://127.0.0.1:8081/
sh two-clients.sh 8081
kill $(jobs -p)
